import os
import unittest

from helpers import TempCase, git, init_repo, read_feature_md, records, run_script, write_file
import paths

migrate_layout = records.load_script("migrate-layout.py")

RUN = "20261105-1304-a1b2c3d-e4f5a6b"
FEATURE_RUN = "20261105-1400-branch-feature"
OLD_FEATURE_MD = (
    "# Feature: Layout\n\nStarted 2026-11-01 in repo. Edit freely above Records.\n\n"
    "## Summary\n\nMove the files.\n\n## Records\n\nRegenerated by records.py.\n\n- **DEC-1** decision\n\n"
    "## History\n\n- **STORM-2** brainstorm\n"
)
RECORD = "---\nid: DEC-1\ntype: decision\ntitle: Keep the ledger hidden\nstatus: active\n---\n\n# DEC-1. Keep the ledger hidden\n\n## Decision\n\nHide it.\n"
OVERVIEW = "# Overview\n\nGenerated 2026-11-02 through DEC-1 (basis 0123456789).\n"
WORKSPACE = "# Review workspace\n"
USER_FILES = {"notes/troubleshooting.md": "my notes\n", "logs/api.log": "a log line\n"}


def old(wt, name):
    return os.path.join(paths.clerk_dev(wt), name)


def read(path):
    with open(path, encoding="utf-8") as f:
        return f.read()


def snapshot(root):
    found = {}
    for here, dirs, files in os.walk(root):
        for name in dirs + files:
            p = os.path.join(here, name)
            found[os.path.relpath(p, root)] = os.readlink(p) if os.path.islink(p) else None if os.path.isdir(p) else read(p)
    return found


def write_old_run(wt, label):
    write_file(os.path.join(old(wt, label), "report.md"), f"---\nrun: .clerk-dev/{label}\n---\n# Review {label}\n")


def write_old_layout(wt):
    write_old_run(wt, RUN)
    write_old_run(wt, FEATURE_RUN)
    os.symlink(RUN, old(wt, "latest"))
    os.symlink(FEATURE_RUN, old(wt, "latest-feature"))
    for name in ("build.md", "passes.md", "status-seen-backlog"):
        write_file(old(wt, name), f"old {name}\n")
    write_file(old(wt, "workspace.md"), WORKSPACE)
    write_file(old(wt, "feature/feature.md"), OLD_FEATURE_MD)
    write_file(old(wt, "feature/records/001-decision-keep.md"), RECORD)
    write_file(old(wt, "feature/overview.md"), OVERVIEW)
    write_file(paths.notes(wt), "## Purpose\n\nMove.\n")
    for name, text in USER_FILES.items():
        write_file(old(wt, name), text)


class MigrateCase(TempCase):
    def setUp(self):
        super().setUp()
        self.wt = init_repo(self.path("hub"), with_origin=False).path
        write_old_layout(self.wt)

    def migrate(self, *wts, dry_run=False):
        return run_script("migrate-layout", *(wts or [self.wt]), *(["--dry-run"] if dry_run else []))

    def migrate_ok(self, *wts, dry_run=False):
        code, out = self.migrate(*wts, dry_run=dry_run)
        self.assertEqual(code, 0, out)
        return out


class OldNamesTest(MigrateCase):
    def test_names_each_plugin_file_left_in_the_old_layout(self):
        self.assertEqual(migrate_layout.old_names(self.wt),
                         [RUN, FEATURE_RUN, "build.md", "passes.md", "status-seen-backlog", "workspace.md", "feature", "latest", "latest-feature"])

    def test_names_nothing_once_migrated(self):
        self.migrate_ok()
        self.assertEqual(migrate_layout.old_names(self.wt), [])

    def test_names_nothing_in_a_worktree_without_clerk_dev(self):
        self.assertEqual(migrate_layout.old_names(self.path("empty")), [])


class WhenMigratedTest(MigrateCase):
    def setUp(self):
        super().setUp()
        self.out = self.migrate_ok()

    def test_moves_each_run_into_the_ledger(self):
        self.assertEqual([os.path.isdir(paths.run(self.wt, r)) for r in (RUN, FEATURE_RUN)], [True, True])

    def test_leaves_the_run_contents_as_they_were(self):
        self.assertEqual(read(os.path.join(paths.run(self.wt, RUN), "report.md")), f"---\nrun: .clerk-dev/{RUN}\n---\n# Review {RUN}\n")

    def test_moves_the_ledger_files(self):
        moved = [read(f(self.wt)) for f in (paths.build_log, paths.passes, paths.seen_backlog)]
        self.assertEqual(moved, ["old build.md\n", "old passes.md\n", "old status-seen-backlog\n"])

    def test_moves_the_workspace_manifest(self):
        self.assertEqual(read(paths.workspace(self.wt)), WORKSPACE)

    def test_leaves_only_the_user_facing_files_and_the_users_own_on_top(self):
        self.assertEqual(sorted(os.listdir(paths.clerk_dev(self.wt))),
                         [".ledger", "branch-notes.md", "feature.md", "logs", "notes", "overview.md", "review-feature.md", "review.md"])

    def test_leaves_the_users_notes_and_logs(self):
        self.assertEqual({n: read(old(self.wt, n)) for n in USER_FILES}, USER_FILES)

    def test_points_latest_at_the_moved_run(self):
        self.assertEqual(os.readlink(paths.latest(self.wt)), f"runs/{RUN}")

    def test_points_latest_feature_at_the_moved_feature_run(self):
        self.assertEqual(os.readlink(paths.latest(self.wt, feature=True)), f"runs/{FEATURE_RUN}")

    def test_review_md_reads_the_latest_runs_report(self):
        self.assertIn(f"# Review {RUN}", read(paths.review_link(self.wt)))

    def test_review_feature_md_reads_the_feature_runs_report(self):
        self.assertIn(f"# Review {FEATURE_RUN}", read(paths.review_link(self.wt, feature=True)))

    def test_moves_the_records(self):
        self.assertEqual(os.listdir(paths.records_dir(self.wt)), ["001-decision-keep.md"])

    def test_moves_the_overview_to_the_top(self):
        self.assertEqual(read(paths.overview(self.wt)), OVERVIEW)

    def test_the_feature_meta_keeps_only_the_name_and_summary(self):
        self.assertEqual(read(paths.feature_meta(self.wt)),
                         "# Feature: Layout\n\nStarted 2026-11-01 in repo. Edit freely.\n\n## Summary\n\nMove the files.\n")

    def test_makes_feature_md_from_the_records(self):
        self.assertIn("### DEC-1. Keep the ledger hidden", read_feature_md(self.wt))

    def test_says_each_move(self):
        self.assertIn(f"{self.wt}: move .clerk-dev/build.md -> .clerk-dev/.ledger/build.md", self.out)

    def test_a_second_run_does_nothing(self):
        self.assertEqual(self.migrate_ok(), f"{self.wt}: already in the new layout; nothing to move")


class WhenAnotherWorktreeLinksToTheManifestTest(MigrateCase):
    def setUp(self):
        super().setUp()
        self.other = self.path("other")
        git(self.wt, "worktree", "add", "-q", "-b", "feat/other", self.other)
        os.makedirs(paths.clerk_dev(self.other))
        os.symlink(old(self.wt, "workspace.md"), old(self.other, "workspace.md"))
        self.migrate_ok(self.wt, self.other)

    def test_points_its_link_at_the_hubs_ledger_manifest(self):
        self.assertEqual(os.readlink(paths.workspace(self.other)), paths.workspace(self.wt))

    def test_its_link_reads_the_manifest(self):
        self.assertEqual(read(paths.workspace(self.other)), WORKSPACE)

    def test_removes_its_old_link(self):
        self.assertFalse(os.path.lexists(old(self.other, "workspace.md")))


class DryRunTest(MigrateCase):
    def setUp(self):
        super().setUp()
        self.before = snapshot(paths.clerk_dev(self.wt))
        self.out = self.migrate_ok(dry_run=True)

    def test_changes_nothing(self):
        self.assertEqual(snapshot(paths.clerk_dev(self.wt)), self.before)

    def test_lists_the_moves(self):
        self.assertIn(f"{self.wt}: move .clerk-dev/{RUN} -> .clerk-dev/.ledger/runs/{RUN}", self.out)

    def test_lists_the_links(self):
        self.assertIn(f"{self.wt}: link .clerk-dev/review.md -> .ledger/runs/{RUN}/report.md", self.out)

    def test_lists_feature_md(self):
        self.assertIn(f"{self.wt}: make .clerk-dev/feature.md", self.out)


class WhenADestinationHoldsSomethingElseTest(MigrateCase):
    def setUp(self):
        super().setUp()
        write_file(paths.build_log(self.wt), "new build.md\n")
        self.code, self.out = self.migrate()

    def test_exits_1(self):
        self.assertEqual(self.code, 1)

    def test_reports_the_conflict(self):
        self.assertIn(f"{self.wt}: conflict: .clerk-dev/.ledger/build.md exists and differs from .clerk-dev/build.md; left as it is", self.out)

    def test_leaves_both(self):
        self.assertEqual([read(old(self.wt, "build.md")), read(paths.build_log(self.wt))], ["old build.md\n", "new build.md\n"])

    def test_still_moves_the_rest(self):
        self.assertEqual(read(paths.passes(self.wt)), "old passes.md\n")


class WhenADestinationHoldsTheSameTest(MigrateCase):
    def setUp(self):
        super().setUp()
        write_file(paths.build_log(self.wt), "old build.md\n")
        self.migrate_ok()

    def test_removes_the_old_copy(self):
        self.assertFalse(os.path.lexists(old(self.wt, "build.md")))


class RefusalTest(TempCase):
    def refusal(self, wt):
        code, out = run_script("migrate-layout", wt)
        self.assertNotEqual(code, 0)
        return out

    def test_refuses_a_directory_outside_git(self):
        os.makedirs(paths.clerk_dev(self.path("plain")))
        self.assertIn("is not a git worktree", self.refusal(self.path("plain")))

    def test_refuses_a_worktree_without_clerk_dev(self):
        self.assertIn("has no .clerk-dev/ directory", self.refusal(init_repo(self.path("bare"), with_origin=False).path))


class WhenTheWorktreeHasTheNewLayoutTest(TempCase):
    def test_does_nothing(self):
        wt = init_repo(self.path("new"), with_origin=False).path
        paths.ensure(wt)
        write_file(paths.build_log(wt), "new\n")
        self.assertEqual(run_script("migrate-layout", wt), (0, f"{wt}: already in the new layout; nothing to move"))


if __name__ == "__main__":
    unittest.main()
